mapper.select:
select from cms_registration r where r.member_id in
#{memberId}
and r.payment_time is not null and r.payment_status in (2, 4) and r.payment_time < #{toExclusive} order by r.member_id asc, r.payment_time asc, r.id asc

select distinct r.member_id
from cms_registration r
left join cms_activity a on r.owner_type = 2 and a.id = r.owner_id
where r.member_id is not null
  and r.payment_time is not null
  and r.payment_time >= #{from}
  and r.payment_time < #{toExclusive}
  and  in
  #{topicId}
order by r.member_id asc
